def audit_report(scans):
    unique = set(scans)
    freq_map = {}
    for item in unique:
        freq_map[item] = scans.count(item)  # O(n) per item
    max_freq = max(freq_map.values())
    candidates = [k for k, v in freq_map.items() if v == max_freq]
    return freq_map, min(candidates)

