def audit_report(scans):
    freq_map = {}
    best_id = scans[0]
    best_freq = 0
    for item in scans:
        freq_map[item] = freq_map.get(item, 0) + 1
        f = freq_map[item]
        # Update best: higher freq wins; tie goes to smaller ID
        if f > best_freq or (f == best_freq and item < best_id):
            best_freq = f
            best_id = item
    return freq_map, best_id

