def count_segments(fuel, k):
    count = 0
    n = len(fuel)
    for i in range(n):
        total = 0
        for j in range(i, n):
            total += fuel[j]
            if total == k:
                count += 1
    return count

def shift_demand(n, pref):
    demand = []
    for s in range(1, n + 1):
        count = sum(1 for driver in pref if s in driver)
        demand.append(count)
    return demand

