def shift_demand(n, pref):
    # Use a dict to count demand per shift ID
    freq = {}
    for driver_prefs in pref:
        for shift in driver_prefs:
            freq[shift] = freq.get(shift, 0) + 1
    # Build result list for shifts 1..n (0-indexed output)
    return [freq.get(s, 0) for s in range(1, n + 1)]
